/**
 * @file network_parity_tests.cpp
 * @brief The networks generated from graph.json are exactly the networks of FlightLearner.
 *
 * FlightLearner writes a checkpoint; this test reads its actor, log-std and critic into the
 * rl_tools networks generated by PPOKit from task.json + graph.json, then checks that the
 * generated actor produces the same means, bit for bit, on probe observations. Reading the
 * whole file without leftover proves that every layer of the generated networks has the
 * size of the hand-written ones.
 */
#include "flight_learner.hpp"
#include "flight_rng_checkpoint.hpp"
#include "test_support.hpp"

#include <rl_tools/operations/cpu_mux.h>
#include <rl_tools/nn/operations_cpu_mux.h>
#include <rl_tools/nn_models/mlp_unconditional_stddev/operations_generic.h>
#include <rl_tools/nn/optimizers/adam/operations_generic.h>

#include "flight_networks.hpp"

#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <memory>
#include <string>

using namespace ppo::examples::flight;

namespace {

namespace rlt = rl_tools;
namespace generated = task::networks;
using Device = rlt::devices::DEVICE_FACTORY<>;
using Index = typename Device::index_t;
/** @brief FlightLearner evaluates one observation at a time on static matrices. */
constexpr Index SingleSample = 1;
using ActorNetwork = generated::Actor::Network<Index, SingleSample, generated::Actor::DefaultWidth, rlt::MatrixStaticTag>;
using CriticNetwork =
    generated::Critic::Network<Index, SingleSample, generated::Critic::DefaultWidth, rlt::MatrixStaticTag>;
template<Index Columns>
using Row = rlt::MatrixStatic<rlt::matrix::Specification<float, Index, 1, Columns>>;

/** @brief Reads one matrix written row-major by FlightLearner. */
template<typename Matrix>
void ReadMatrix(std::istream& stream, Matrix& matrix)
{
    for (Index row = 0; row < Matrix::ROWS; ++row)
    {
        for (Index column = 0; column < Matrix::COLS; ++column)
        {
            float value{};
            Check(static_cast<bool>(stream >> value), "checkpoint ends before the generated network is filled");
            rlt::set(matrix, row, column, value);
        }
    }
}

/** @brief A parameter is stored with its two Adam moments. */
template<typename Parameter>
void ReadParameter(std::istream& stream, Parameter& parameter)
{
    ReadMatrix(stream, parameter.parameters);
    ReadMatrix(stream, parameter.gradient_first_order_moment);
    ReadMatrix(stream, parameter.gradient_second_order_moment);
}

template<typename Layer>
void ReadLayer(std::istream& stream, Layer& layer)
{
    ReadParameter(stream, layer.weights);
    ReadParameter(stream, layer.biases);
}

/** @brief Layers in the checkpoint order: input, hidden, output. */
template<typename Network>
void ReadNetwork(std::istream& stream, Network& network)
{
    ReadLayer(stream, network.input_layer);
    for (auto& layer : network.hidden_layers)
    {
        ReadLayer(stream, layer);
    }
    ReadLayer(stream, network.output_layer);
}

/** @brief Skips the header, the quoted signature, the Adam ages and the RNG state. */
void SkipCheckpointPreamble(std::istream& stream)
{
    std::string magic;
    std::size_t observations{};
    std::size_t actions{};
    std::size_t outputs{};
    std::size_t width{};
    std::uint64_t updates{};
    std::string signature;
    std::uint64_t actorAge{};
    std::uint64_t criticAge{};
    stream >> magic >> observations >> actions >> outputs >> width >> updates >> std::quoted(signature) >> actorAge
        >> criticAge;
    Check(static_cast<bool>(stream), "readable checkpoint header");
    Check(observations == generated::Actor::Inputs && outputs == generated::Actor::Outputs,
        "checkpoint sizes match graph.json");
    Check(width == generated::Actor::DefaultWidth, "checkpoint width matches graph.json");
    detail::ReadCheckpointRng(stream);
}

/** @brief Deterministic observation inside the normalized [-1, 1] range. */
Observation Probe(int seed)
{
    Observation observation{};
    for (std::size_t index = 0; index < observation.size(); ++index)
    {
        auto const phase = static_cast<double>(seed * 31 + static_cast<int>(index) * 7);
        observation[index] = static_cast<float>(0.9 * std::sin(phase));
    }
    return observation;
}

void GeneratedNetworksReproduceTheLearner()
{
    auto const config = LoadConfig(PPO_FLIGHT_CONFIG);
    Check(config.training.hiddenWidth == generated::Actor::DefaultWidth,
        "graph.json width equals training.hiddenWidth of the scenario");
    FlightLearner learner(config);
    TemporaryDirectory directory("flight-network-parity-");
    auto const checkpoint = directory.path / "policy.txt";
    learner.Save(checkpoint);

    // Static rl_tools networks hold self-pointers and are large: keep them on the heap.
    auto actor = std::make_unique<ActorNetwork>();
    auto critic = std::make_unique<CriticNetwork>();
    std::ifstream stream(checkpoint);
    SkipCheckpointPreamble(stream);
    ReadNetwork(stream, *actor);
    ReadParameter(stream, actor->log_std);
    ReadNetwork(stream, *critic);
    stream >> std::ws;
    Check(stream.eof(), "the generated networks consume the whole checkpoint");

    Device device;
    Row<generated::Actor::Inputs> input;
    Row<generated::Actor::Outputs> output;
    for (int seed = 0; seed < 8; ++seed)
    {
        auto const observation = Probe(seed);
        for (Index index = 0; index < generated::Actor::Inputs; ++index)
        {
            rlt::set(input, 0, index, observation[index]);
        }
        rlt::forward(device, *actor, input, output);
        auto const expected = learner.Evaluate(observation);
        for (Index index = 0; index < generated::Actor::Outputs; ++index)
        {
            Check(static_cast<double>(rlt::get(output, 0, index)) == expected.output[index],
                "generated actor mean equals FlightLearner bit for bit");
            Check(static_cast<double>(rlt::get(actor->log_std.parameters, 0, index))
                    == expected.logStandardDeviations[index],
                "generated log-std equals FlightLearner");
        }
    }
}

} // namespace

int main()
{
    try
    {
        GeneratedNetworksReproduceTheLearner();
        std::cout << "PPOKit networks reproduce the FlightControl3D learner bit for bit\n";
        return 0;
    }
    catch (std::exception const& error)
    {
        std::cerr << "FAILED: " << error.what() << '\n';
        return 1;
    }
}
